p02-growth:
def solve(
    initial: float,
    factor: float,
    steps: int,
) -> list[float]:
    return growth(initial, factor, steps)

def growth(initial, factor, steps):
    values = [initial]
    for _ in range(steps):
        values.append(factor * values[-1])
    return values

p02-varying-steps:
def solve(
    A0: float,
    rates: list[float],
    durations: list[float],
    k: float,
) -> tuple[list[float], float]:
    return varying(A0, rates, durations, k)

def varying(A0, rates, durations, k):
    amounts, total = [A0], 0.0
    for rate, duration in zip(rates, durations):
        total += rate * duration
        amounts.append(amounts[-1] + duration * (rate - k * amounts[-1]))
    return amounts, total

p02-difference:
def solve(
    t: float,
    h: float,
) -> float:
    return forward_difference(t, h)

def forward_difference(t, h):
    return ((t + h)**2 - t**2) / h

p02-left-area:
def solve(
    start: float,
    end: float,
    intervals: int,
) -> float:
    return left_area(start, end, intervals)

def left_area(start, end, intervals):
    h = (end - start) / intervals
    total = 0.0
    for i in range(intervals):
        time = start + i * h
        total += (2 * time) * h
    return total

p02-chain-rule:
def solve(
    k: float,
    times: list[float],
) -> tuple[list[float], list[float]]:
    return exponential_pair(k, times)

def exponential_pair(k, times):
    import math
    values = [math.exp(-k * t) for t in times]
    derivatives = [-k * value for value in values]
    return values, derivatives

p02-exact:
def solve(
    A0: float,
    u: float,
    k: float,
    times: list[float],
) -> list[float]:
    return exact_series(A0, u, k, times)

def exact_amount(time, u, k, A0):
    import math
    if k == 0:
        return A0 + u * time
    # expm1(z)/z tends to 1; this avoids both cancellation and a huge u/k.
    z = -k * time
    ratio = 1.0 if z == 0 else math.expm1(z) / z
    return A0 * math.exp(z) + u * time * ratio

def exact_series(A0, u, k, times):
    return [exact_amount(t, u, k, A0) for t in times]

p02-arrival:
def solve(
    k: float,
    fractions: list[float],
) -> list[float]:
    return fraction_times(k, fractions)

def fraction_times(k, fractions):
    import math
    return [-math.log1p(-f) / k for f in fractions]

p02-errors:
def solve(
    A0: float,
    u: float,
    k: float,
    step_sizes: list[float],
    end: float,
) -> list[float]:
    return grid_errors(A0, u, k, step_sizes, end)

def euler(A0, u, k, h, steps):
    amounts = [A0]
    residuals = []
    for _ in range(steps):
        before = amounts[-1]
        incoming = h * u
        removed = h * k * before
        after = before + incoming - removed
        amounts.append(after)
        residuals.append(after - before - incoming + removed)
    return amounts, residuals

def exact_amount(time, u, k, A0):
    import math
    if k == 0:
        return A0 + u * time
    # expm1(z)/z tends to 1; this avoids both cancellation and a huge u/k.
    z = -k * time
    ratio = 1.0 if z == 0 else math.expm1(z) / z
    return A0 * math.exp(z) + u * time * ratio

def exact_series(A0, u, k, times):
    return [exact_amount(t, u, k, A0) for t in times]

def grid_errors(A0, u, k, step_sizes, end):
    errors = []
    for h in step_sizes:
        steps = round(end / h)
        amounts, _ = euler(A0, u, k, h, steps)
        errors.append(max(abs(a - exact_amount(i * h, u, k, A0))
                          for i, a in enumerate(amounts)))
    return errors

p02-orders:
def solve(
    errors: list[float],
) -> list[float]:
    return observed_orders(errors)

def observed_orders(errors):
    import math
    return [math.log2(a / b) for a, b in zip(errors, errors[1:])]

p02-step-properties:
def solve(
    k: float,
    h: float,
) -> tuple[float, bool, bool]:
    return step_properties(k, h)

def step_properties(k, h):
    q = 1 - k * h
    return q, abs(q) < 1, q >= 0

p02-first-decay:
def solve(
    A0: float,
    k: float,
    step_sizes: list[float],
) -> list[float]:
    return first_decay(A0, k, step_sizes)

def first_decay(A0, k, step_sizes):
    return [A0 * (1 - k * h) for h in step_sizes]

p02-aligned-grid:
def solve(
    bounds: list[float],
    h: float,
) -> list[float]:
    return aligned_grid(bounds, h)

def aligned_grid(bounds, h):
    import math
    times = [bounds[0]]
    for left, right in zip(bounds, bounds[1:]):
        count = math.ceil((right - left) / h - 1e-12)
        for i in range(1, count + 1):
            # Restart at each change point, keeping the exact final boundary.
            times.append(right if i == count else left + i * h)
    return times

p02-input-totals:
def solve(
    bounds: list[float],
    plans: list[list[float]],
) -> list[float]:
    return input_totals(bounds, plans)

def input_totals(bounds, plans):
    totals = []
    for rates in plans:
        totals.append(sum((b - a) * rate for a, b, rate in zip(bounds, bounds[1:], rates)))
    return totals
